        if command == "order":
            print("What would you like to order? (coffee/pastry)")
            drink = input("Enter your drink: ").lower()

            if drink == "coffee":
                order.append("coffee")
            elif drink == "pastry":
                order.append("pastry")
            else:
                print("Invalid input. Please enter 'coffee' or 'pastry'.")

        elif command == "check":
            if order:
                print("Current Order:")
                for item in order:
                    print(f"- {item}")
            else:
                print("No order has been placed yet.")

        elif command == "quit":
            break

        else:
            print("Invalid command. Please enter 'order', 'check', or 'quit'.")

    print("Thank you for using the Coffee Shop Simulator!")


if __name__ == "__main__":
    simulate_coffee_shop()
```

